BridgeResources(Resources base){super(base.getAssets(),base.getDisplayMetrics(),base.getConfiguration());}
 private String own(int id){int i=id-BASE;if(i<0||i>=EN.length)return null;String lang=locale().getLanguage();return (lang.equals("zh")?ZH:lang.equals("it")?IT:EN)[i];}
 private Locale locale(){Configuration c=getConfiguration();return android.os.Build.VERSION.SDK_INT>=24?c.getLocales().get(0):c.locale;}
 @Override public CharSequence getText(int id){String s=own(id);return s==null?super.getText(id):s;}
 @Override public CharSequence getText(int id,CharSequence def){String s=own(id);return s==null?super.getText(id,def):s;}
 @Override public String getString(int id){String s=own(id);return s==null?super.getString(id):s;}
 @Override public String getString(int id,Object... args){String s=own(id);return s==null?super.getString(id,args):String.format(locale(),s,args);}
